export PYTHONUTF8=1 LANG=C.UTF-8; cd /work; python3 -c 'import json,urllib.request,re
hdr={"User-Agent":"claim-audit","Accept":"application/vnd.github+json"}
status=None; src=None
try:
    svg=urllib.request.urlopen(urllib.request.Request("https://github.com/python-humanize/humanize/workflows/Test/badge.svg",headers={"User-Agent":"claim-audit"}),timeout=20).read().decode("utf-8","replace")
    m=re.search(r"(passing|failing|no status|unknown)",svg)
