except Exception as e:
    src="badge fetch error %r" % e
if status is None:
    try:
        wf=json.load(urllib.request.urlopen(urllib.request.Request("https://api.github.com/repos/python-humanize/humanize/actions/workflows",headers=hdr),timeout=20))
        wid=[w["id"] for w in wf["workflows"] if w["name"]=="Test"][0]
        runs=json.load(urllib.request.urlopen(urllib.request.Request("https://api.github.com/repos/python-humanize/humanize/actions/workflows/%d/runs?branch=main&status=completed&per_page=1" % wid,headers=hdr),timeout=20))
        status="passing" if runs["workflow_runs"][0]["conclusion"]=="success" else runs["workflow_runs"][0]["conclusion"]; src="github api latest completed run on main: "+runs["workflow_runs"][0]["html_url"]
    except Exception as e:
        src=str(src)+"; api error %r" % e
print("CLAIM c11: %s Test workflow badge status=%r (source: %s)" % ("PASS" if status=="passing" else "FAIL", status, src))'
